if is_even(n):
    print("Even")
else:
    print("Odd")

def calculate_bill(amount, tax=5):
    return amount + (amount * tax / 100)

print(f"Bill with default tax: {calculate_bill(1000):.2f}")
print(f"Bill with 12% tax: {calculate_bill(1000, tax=12):.2f}")

def sorted_copy(values):
    return sorted(values)

nums = list(map(int, input().split()))
sorted_nums = sorted_copy(nums)
print(f"Original: {nums}")
print(f"Sorted: {sorted_nums}")

def sum_to(n):
    if n <= 0:
        return 0
    return n + sum_to(n - 1)

n = int(input())
print(sum_to(n))

def halvings(n):
    if n <= 1:
        return 0
    return 1 + halvings(n // 2)

n = int(input())
print(f"Steps: {halvings(n)}")

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

n = int(input())
print(factorial(n))

def power(base, exp):
    if exp == 0:
        return 1
    return base * power(base, exp - 1)

base = int(input())
exp = int(input())
print(power(base, exp))

def sum_digits(n):
    if n < 10:
        return n
    return (n % 10) + sum_digits(n // 10)

n = int(input())
print(sum_digits(n))

def count_digits(n):
    if n < 10:
        return 1
    return 1 + count_digits(n // 10)

n = int(input())
print(f"Digits: {count_digits(n)}")

def fib(n):
    if n <= 1:
        return n
    return fib(n - 1) + fib(n - 2)

n = int(input())
print(f"fib({n}) = {fib(n)}")

def reverse_text(s):
    if len(s) <= 1:
        return s
    return reverse_text(s[1:]) + s[0]

word = input().strip()
print(reverse_text(word))

def is_pal(s):
    if len(s) <= 1:
        return True
    if s[0] != s[-1]:
        return False
    return is_pal(s[1:-1])

word = input().strip()
print("Palindrome" if is_pal(word) else "Not a palindrome")

def count_vowels(s):
    if not s:
        return 0
    is_v = 1 if s[0].lower() in "aeiou" else 0
    return is_v + count_vowels(s[1:])

word = input().strip()
print(f"Vowels: {count_vowels(word)}")

def remove_spaces(s):
    if not s:
        return ""
    head = "" if s[0] == " " else s[0]
    return head + remove_spaces(s[1:])

line = input()
print(remove_spaces(line))

def sum_list(nums):
    if not nums:
        return 0
    return nums[0] + sum_list(nums[1:])

nums = list(map(int, input().split()))
print(f"Sum: {sum_list(nums)}")

def nested_sum(items):
    total = 0
    for item in items:
        if isinstance(item, list):
            total += nested_sum(item)
        else:
            total += item
    return total

data = [1, [2, 3], [4, [5]]]
print(f"Total: {nested_sum(data)}")

def depth(items):
    max_depth = 1
    for item in items:
        if isinstance(item, list):
            d = 1 + depth(item)
            if d > max_depth:
                max_depth = d
    return max_depth

data = [1, [2, [3]]]
print(f"Depth: {depth(data)}")

def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)

a = int(input())
b = int(input())
print(f"GCD: {gcd(a, b)}")

def binary_search(items, target, low, high):
    if low > high:
        return -1
    mid = (low + high) // 2
    if items[mid] == target:
        return mid
    elif items[mid] > target:
        return binary_search(items, target, low, mid - 1)
    else:
        return binary_search(items, target, mid + 1, high)

items = [2, 5, 8, 12, 16, 23, 38, 56, 72, 91]
target = int(input())
idx = binary_search(items, target, 0, len(items) - 1)
print(f"Found at index {idx}" if idx != -1 else "Not found")

def to_binary(n):
    if n < 2:
        return str(n)
    return to_binary(n // 2) + str(n % 2)

n = int(input())
print(f"Binary: {to_binary(n)}")
